import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1784485118000}'),s={name:"architecture.md"};function o(i,t,d,l,c,g){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>The Ahmed Enterprise AI Workspace is built on an <strong>8-Layer Architecture</strong> designed for enterprise-grade AI engineering. This document explains how each layer works and how components interact.</p><h2 id="_8-layer-workspace-model" tabindex="-1">8-Layer Workspace Model <a class="header-anchor" href="#_8-layer-workspace-model" aria-label="Permalink to &quot;8-Layer Workspace Model&quot;">​</a></h2><div class="mermaid">graph TB subgraph &quot;Layer 8: Future&quot; F[Future Layer] F --&gt; F1[Plugin System] F --&gt; F2[Experimental Features] F --&gt; F3[Multi-project Management] end subgraph &quot;Layer 7: Automation&quot; A[Automation Layer] A --&gt; A1[Commands] A --&gt; A2[Workflows] A --&gt; A3[Templates] end subgraph &quot;Layer 6: Knowledge&quot; K[Knowledge Layer] K --&gt; K1[Memory] K --&gt; K2[Decisions] K --&gt; K3[Learnings] end subgraph &quot;Layer 5: Security&quot; S[Security Layer] S --&gt; S1[Authentication] S --&gt; S2[Secrets Management] S --&gt; S3[Compliance] end subgraph &quot;Layer 4: Quality&quot; Q[Quality Layer] Q --&gt; Q1[Testing] Q --&gt; Q2[Review] Q --&gt; Q3[Accessibility] Q --&gt; Q4[Performance] end subgraph &quot;Layer 3: Domain&quot; D[Domain Layer] D --&gt; D1[Skills] D --&gt; D2[Agent Expertise] D --&gt; D3[Domain Knowledge] end subgraph &quot;Layer 2: Professional&quot; P[Professional Layer] P --&gt; P1[Coding Standards] P --&gt; P2[Architecture Standards] P --&gt; P3[Documentation Standards] end subgraph &quot;Layer 1: Personal&quot; PL[Personal Layer] PL --&gt; PL1[Ahmed&#39;s Preferences] PL --&gt; PL2[Style Guide] PL --&gt; PL3[Conventions] end F --&gt; A A --&gt; K K --&gt; S S --&gt; Q Q --&gt; D D --&gt; P P --&gt; PL style F fill:#e1f5fe style A fill:#f3e5f5 style K fill:#e8f5e9 style S fill:#fff3e0 style Q fill:#fce4ec style D fill:#f3e5f5 style P fill:#e0f2f1 style PL fill:#fffde7 </div><h3 id="layer-descriptions" tabindex="-1">Layer Descriptions <a class="header-anchor" href="#layer-descriptions" aria-label="Permalink to &quot;Layer Descriptions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Scope</th><th>Mutability</th><th>Description</th></tr></thead><tbody><tr><td><strong>Personal</strong></td><td>Ahmed&#39;s preferences</td><td>User edits</td><td>Style, conventions, RTL-first, bilingual</td></tr><tr><td><strong>Professional</strong></td><td>Universal standards</td><td>Rarely changes</td><td>Coding, architecture, security, quality standards</td></tr><tr><td><strong>Domain</strong></td><td>Engineering knowledge</td><td>Grows over time</td><td>Skills, agent expertise, domain-specific patterns</td></tr><tr><td><strong>Quality</strong></td><td>Testing &amp; review</td><td>Evolves</td><td>Testing, code review, accessibility, performance</td></tr><tr><td><strong>Security</strong></td><td>Auth &amp; compliance</td><td>Stable</td><td>Authentication, secrets, OWASP, audit</td></tr><tr><td><strong>Automation</strong></td><td>Workflows</td><td>Added as needed</td><td>Commands, workflows, templates</td></tr><tr><td><strong>Knowledge</strong></td><td>Memory &amp; decisions</td><td>Accumulates</td><td>ADRs, patterns, lessons, learnings</td></tr><tr><td><strong>Future</strong></td><td>Expansion</td><td>Experimental</td><td>Plugin system, multi-project, advanced features</td></tr></tbody></table><hr><h2 id="agent-system" tabindex="-1">Agent System <a class="header-anchor" href="#agent-system" aria-label="Permalink to &quot;Agent System&quot;">​</a></h2><h3 id="agent-overview" tabindex="-1">Agent Overview <a class="header-anchor" href="#agent-overview" aria-label="Permalink to &quot;Agent Overview&quot;">​</a></h3><p>The workspace includes <strong>22 specialized agents</strong> across all engineering domains.</p><div class="mermaid">flowchart TD User[User Input] --&gt; Router[Domain Router] Router --&gt;|file: src/components/*| FE[Frontend Agent] Router --&gt;|file: src/app/api/*| BE[Backend Agent] Router --&gt;|file: schema/*| DB[Database Agent] Router --&gt;|file: .github/*| DO[DevOps Agent] Router --&gt;|keyword: component, render| FE Router --&gt;|keyword: API, endpoint| BE Router --&gt;|keyword: schema, migration| DB Router --&gt;|keyword: deploy, CI| DO Router --&gt;|keyword: security, auth| SEC[Security Agent] Router --&gt;|keyword: test, coverage| TEST[Tester Agent] Router --&gt;|keyword: performance| PERF[Performance Agent] Router --&gt;|keyword: a11y, WCAG| A11Y[Accessibility Agent] User --&gt;|@agent-name| Direct[Direct Agent Access] FE --&gt; Skills[Skill System] BE --&gt; Skills DB --&gt; Skills DO --&gt; Skills SEC --&gt; Skills TEST --&gt; Skills PERF --&gt; Skills A11Y --&gt; Skills Skills --&gt; Output[Agent Response] Direct --&gt; Output style User fill:#e3f2fd style Router fill:#fff9c4 style Skills fill:#e8f5e9 style Output fill:#f3e5f5 </div><h3 id="primary-agents" tabindex="-1">Primary Agents <a class="header-anchor" href="#primary-agents" aria-label="Permalink to &quot;Primary Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Domain</th><th>Access</th></tr></thead><tbody><tr><td><code>@build</code></td><td>Default, full tool access</td><td>All tools</td></tr><tr><td><code>@plan</code></td><td>Analysis and planning</td><td>Read-only</td></tr></tbody></table><h3 id="domain-agents" tabindex="-1">Domain Agents <a class="header-anchor" href="#domain-agents" aria-label="Permalink to &quot;Domain Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Domain</th><th>Primary Use</th></tr></thead><tbody><tr><td><code>@frontend</code></td><td>React, Tailwind, client-side</td><td>Component creation, styling</td></tr><tr><td><code>@backend</code></td><td>API routes, server logic</td><td>Route handlers, middleware</td></tr><tr><td><code>@database</code></td><td>Schema, queries, migrations</td><td>Database design, optimization</td></tr><tr><td><code>@api-designer</code></td><td>API contracts, REST design</td><td>API versioning, documentation</td></tr><tr><td><code>@architect</code></td><td>System design, patterns</td><td>Refactoring, technical debt</td></tr><tr><td><code>@reviewer</code></td><td>Code quality review</td><td>Pattern consistency</td></tr><tr><td><code>@security</code></td><td>Vulnerability assessment</td><td>Auth review, secrets detection</td></tr><tr><td><code>@tester</code></td><td>Test creation, strategy</td><td>Coverage analysis</td></tr><tr><td><code>@accessibility</code></td><td>WCAG audit, ARIA review</td><td>Keyboard navigation</td></tr><tr><td><code>@performance</code></td><td>Bundle analysis, caching</td><td>Core Web Vitals</td></tr><tr><td><code>@devops</code></td><td>CI/CD, build automation</td><td>Deployment</td></tr><tr><td><code>@cloud</code></td><td>Cloud architecture</td><td>Serverless patterns</td></tr><tr><td><code>@seo</code></td><td>Meta tags, structured data</td><td>Sitemap, Open Graph</td></tr><tr><td><code>@i18n</code></td><td>Translation management</td><td>RTL validation</td></tr><tr><td><code>@ecommerce</code></td><td>Product catalogs, carts</td><td>Checkout, pricing</td></tr><tr><td><code>@ai-engineer</code></td><td>LLM integration, RAG</td><td>Prompt optimization</td></tr><tr><td><code>@context-engineer</code></td><td>Workspace optimization</td><td>AGENTS.md maintenance</td></tr><tr><td><code>@designer</code></td><td>Design systems, tokens</td><td>Typography, motion</td></tr></tbody></table><h3 id="routing-rules" tabindex="-1">Routing Rules <a class="header-anchor" href="#routing-rules" aria-label="Permalink to &quot;Routing Rules&quot;">​</a></h3><p><strong>File-based routing:</strong></p><table tabindex="0"><thead><tr><th>File Path Pattern</th><th>Agent</th></tr></thead><tbody><tr><td><code>src/components/</code>, <code>*.tsx</code> with JSX</td><td>Frontend</td></tr><tr><td><code>src/app/api/</code>, <code>route.ts</code></td><td>Backend + API Designer</td></tr><tr><td><code>src/app/</code> pages</td><td>Frontend</td></tr><tr><td>Schema/migration files</td><td>Database</td></tr><tr><td><code>.github/workflows/</code></td><td>DevOps</td></tr><tr><td><code>src/app/admin/</code></td><td>Frontend + Backend</td></tr><tr><td>Translation files, <code>t()</code> calls</td><td>i18n</td></tr><tr><td><code>*.test.*</code>, <code>*.spec.*</code></td><td>Tester</td></tr><tr><td>Auth/token/security files</td><td>Security</td></tr><tr><td>Meta tags, <code>generateMetadata</code></td><td>SEO</td></tr><tr><td>ARIA, role attributes</td><td>Accessibility</td></tr></tbody></table><p><strong>Priority hierarchy:</strong></p><ol><li>Security findings → always addressed first</li><li>Build-breaking issues → fixed before feature work</li><li>User explicit request → highest intent priority</li><li>Primary agent domain detection → automatic routing</li><li>Skill-triggered loading → on-demand context</li><li>Quality recommendations → advisory</li><li>Performance suggestions → advisory</li></ol><hr><h2 id="skill-system" tabindex="-1">Skill System <a class="header-anchor" href="#skill-system" aria-label="Permalink to &quot;Skill System&quot;">​</a></h2><h3 id="how-skills-work" tabindex="-1">How Skills Work <a class="header-anchor" href="#how-skills-work" aria-label="Permalink to &quot;How Skills Work&quot;">​</a></h3><p>Skills are on-demand knowledge modules loaded when tasks match their descriptions.</p><div class="mermaid">flowchart LR Task[User Task] --&gt; Match{Description Match?} Match --&gt;|Yes| Load[Load Skill] Match --&gt;|No| Skip[Skip Skill] Load --&gt; Inject[Inject Instructions] Inject --&gt; Context[Add to Context] Context --&gt; Execute[Execute Task] Skip --&gt; Execute subgraph &quot;Skill Dependencies&quot; RP[react-patterns] &lt;--&gt; NA[nextjs-app-router] TC[tailwind-css] &lt;--&gt; RD[responsive-design] SA[security-audit] &lt;--&gt; AP[authentication-patterns] SA &lt;--&gt; SM[secrets-management] DD[database-design] &lt;--&gt; SP[supabase-patterns] DD &lt;--&gt; PR[prisma-patterns] AD[api-design] &lt;--&gt; NR[nextjs-route-handlers] WP[web-performance] &lt;--&gt; CS[caching-strategies] WP &lt;--&gt; IO[image-optimization] end style Task fill:#e3f2fd style Match fill:#fff9c4 style Load fill:#e8f5e9 style Skip fill:#ffebee </div><h3 id="skill-categories" tabindex="-1">Skill Categories <a class="header-anchor" href="#skill-categories" aria-label="Permalink to &quot;Skill Categories&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Skills</th><th>Description</th></tr></thead><tbody><tr><td><strong>Frontend</strong></td><td>react-patterns, nextjs-app-router, tailwind-css, responsive-design, form-engineering, state-management, css-motion-design</td><td>React and UI development</td></tr><tr><td><strong>Backend</strong></td><td>api-design, nextjs-route-handlers, background-jobs</td><td>Server-side development</td></tr><tr><td><strong>Database</strong></td><td>database-design, supabase-patterns, prisma-patterns</td><td>Data layer</td></tr><tr><td><strong>Security</strong></td><td>security-audit, authentication-patterns, environment-secrets, jwt-security</td><td>Security practices</td></tr><tr><td><strong>Performance</strong></td><td>web-performance, caching-strategies, image-optimization, bundle-optimization</td><td>Speed optimization</td></tr><tr><td><strong>Quality</strong></td><td>code-review-standards, refactoring-patterns, debug</td><td>Code quality</td></tr><tr><td><strong>Testing</strong></td><td>(tester agent handles)</td><td>Test strategy</td></tr><tr><td><strong>Accessibility</strong></td><td>wcag-checklist, keyboard-navigation, screen-reader-patterns</td><td>A11y compliance</td></tr><tr><td><strong>SEO</strong></td><td>technical-seo, nextjs-seo</td><td>Search optimization</td></tr><tr><td><strong>i18n</strong></td><td>i18n-architecture, rtl-engineering</td><td>Internationalization</td></tr><tr><td><strong>DevOps</strong></td><td>ci-cd-pipelines, vercel-deployment, docker-patterns</td><td>Deployment</td></tr><tr><td><strong>Architecture</strong></td><td>(architect agent reads all)</td><td>System design</td></tr><tr><td><strong>AI</strong></td><td>llm-integration, rag-patterns, prompt-engineering</td><td>AI development</td></tr><tr><td><strong>Workspace</strong></td><td>workspace-optimization</td><td>Self-improvement</td></tr></tbody></table><h3 id="skill-cross-references" tabindex="-1">Skill Cross-References <a class="header-anchor" href="#skill-cross-references" aria-label="Permalink to &quot;Skill Cross-References&quot;">​</a></h3><p>Skills reference each other for complementary knowledge:</p><div class="mermaid">graph LR RP[react-patterns] --- NA[nextjs-app-router] TC[tailwind-css] --- RD[responsive-design] SA[security-audit] --- AP[authentication-patterns] SA --- SM[secrets-management] DD[database-design] --- SP[supabase-patterns] DD --- PR[prisma-patterns] AD[api-design] --- NR[nextjs-route-handlers] WP[web-performance] --- CS[caching-strategies] WP --- IO[image-optimization] WC[wcag-checklist] --- KN[keyboard-navigation] WC --- SR[screen-reader-patterns] style RP fill:#e3f2fd style NA fill:#e3f2fd style TC fill:#e8f5e9 style RD fill:#e8f5e9 style SA fill:#fff3e0 style AP fill:#fff3e0 style SM fill:#fff3e0 </div><hr><h2 id="command-system" tabindex="-1">Command System <a class="header-anchor" href="#command-system" aria-label="Permalink to &quot;Command System&quot;">​</a></h2><h3 id="command-execution-flow" tabindex="-1">Command Execution Flow <a class="header-anchor" href="#command-execution-flow" aria-label="Permalink to &quot;Command Execution Flow&quot;">​</a></h3><div class="mermaid">sequenceDiagram participant U as User participant C as Command Parser participant A as Agent Router participant S as Skill System participant T as Tool Execution U-&gt;&gt;C: /command-name C-&gt;&gt;C: Parse command C-&gt;&gt;A: Route to agent A-&gt;&gt;S: Load relevant skills S-&gt;&gt;A: Inject domain knowledge A-&gt;&gt;T: Execute with tools T-&gt;&gt;A: Return results A-&gt;&gt;U: Present output </div><h3 id="command-categories" tabindex="-1">Command Categories <a class="header-anchor" href="#command-categories" aria-label="Permalink to &quot;Command Categories&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Commands</th><th>Description</th></tr></thead><tbody><tr><td><strong>Review</strong></td><td><code>/review</code>, <code>/security-scan</code>, <code>/performance-check</code>, <code>/a11y-audit</code>, <code>/seo-check</code></td><td>Code analysis</td></tr><tr><td><strong>Generation</strong></td><td><code>/new-page</code>, <code>/new-api</code>, <code>/new-component</code></td><td>Create new files</td></tr><tr><td><strong>Refactoring</strong></td><td><code>/refactor</code></td><td>Improve existing code</td></tr><tr><td><strong>Deployment</strong></td><td><code>/deploy-check</code></td><td>Deployment readiness</td></tr><tr><td><strong>Documentation</strong></td><td><code>/generate-docs</code></td><td>Create documentation</td></tr><tr><td><strong>Workspace</strong></td><td><code>/health-check</code>, <code>/workspace-audit</code>, <code>/workspace-validate</code>, <code>/self-improve</code></td><td>Workspace management</td></tr><tr><td><strong>Creation</strong></td><td><code>/create-skill</code>, <code>/create-agent</code>, <code>/create-command</code>, <code>/create-playbook</code></td><td>Extend the workspace</td></tr></tbody></table><hr><h2 id="knowledge-accumulation" tabindex="-1">Knowledge Accumulation <a class="header-anchor" href="#knowledge-accumulation" aria-label="Permalink to &quot;Knowledge Accumulation&quot;">​</a></h2><h3 id="how-knowledge-grows" tabindex="-1">How Knowledge Grows <a class="header-anchor" href="#how-knowledge-grows" aria-label="Permalink to &quot;How Knowledge Grows&quot;">​</a></h3><p>The workspace accumulates knowledge over time through decisions, patterns, and learnings.</p><div class="mermaid">flowchart TD A[New Pattern Established] --&gt;|Add to AGENTS.md| B[Project Patterns] C[Bug Root Cause Found] --&gt;|Add to AGENTS.md| D[Known Issues] E[Architecture Decision] --&gt;|Add ADR or note| F[Decisions] G[New Convention Adopted] --&gt;|Add to AGENTS.md| H[Conventions] I[Performance Lesson] --&gt;|Add to skill| J[Skill Knowledge] K[Security Finding] --&gt;|Add to AGENTS.md| L[Security Notes] B --&gt; M[Workspace Memory] D --&gt; M F --&gt; M H --&gt; M J --&gt; M L --&gt; M M --&gt; N[Improved Agent Responses] N --&gt; A style A fill:#e8f5e9 style C fill:#ffebee style E fill:#e3f2fd style G fill:#fff9c4 style I fill:#f3e5f5 style K fill:#fff3e0 </div><h3 id="anti-patterns-never-store" tabindex="-1">Anti-Patterns (Never Store) <a class="header-anchor" href="#anti-patterns-never-store" aria-label="Permalink to &quot;Anti-Patterns (Never Store)&quot;">​</a></h3><ul><li>Credentials or secrets</li><li>Temporary workarounds (mark as <code>[TEMP]</code> and remove later)</li><li>Duplicate information across layers</li><li>Information that belongs in code</li><li>Speculative future requirements</li></ul><hr><h2 id="dependency-graph" tabindex="-1">Dependency Graph <a class="header-anchor" href="#dependency-graph" aria-label="Permalink to &quot;Dependency Graph&quot;">​</a></h2><p>The full dependency graph shows how agents, skills, and commands relate:</p><div class="mermaid">graph TB subgraph &quot;Agents&quot; BUILD[build] PLAN[plan] FE[frontend] BE[backend] DB[database] SEC[security] REV[reviewer] TEST[tester] PERF[performance] A11Y[accessibility] DO[devops] SEO[seo] I18N[i18n] ARCH[architect] end subgraph &quot;Skills&quot; RP[react-patterns] NA[nextjs-app-router] TC[tailwind-css] RD[responsive-design] AD[api-design] DD[database-design] SA[security-audit] CR[code-review-standards] WP[web-performance] WC[wcag-checklist] TSEO[technical-seo] II[i18n-architecture] CICD[ci-cd-pipelines] end subgraph &quot;Commands&quot; REVIEW[/review] SSCAN[/security-scan] PCHECK[/performance-check] A11YAUDIT[/a11y-audit] SEOCHK[/seo-check] NPAGE[/new-page] NAPI[/new-api] NCOMP[/new-component] REFACTOR[/refactor] DCHK[/deploy-check] end BUILD --&gt; RP BUILD --&gt; NA BUILD --&gt; TC PLAN --&gt; REV PLAN --&gt; ARCH PLAN --&gt; SEC FE --&gt; RP FE --&gt; NA FE --&gt; TC FE --&gt; RD BE --&gt; AD DB --&gt; DD SEC --&gt; SA REV --&gt; CR PERF --&gt; WP A11Y --&gt; WC SEO --&gt; TSEO I18N --&gt; II DO --&gt; CICD REVIEW --&gt; REV SSCAN --&gt; SEC PCHECK --&gt; PERF A11YAUDIT --&gt; A11Y SEOCHK --&gt; SEO NPAGE --&gt; FE NAPI --&gt; BE NCOMP --&gt; FE REFACTOR --&gt; ARCH DCHK --&gt; DO style BUILD fill:#e3f2fd style FE fill:#e8f5e9 style BE fill:#fff3e0 style DB fill:#f3e5f5 style SEC fill:#ffebee </div><hr><h2 id="configuration-system" tabindex="-1">Configuration System <a class="header-anchor" href="#configuration-system" aria-label="Permalink to &quot;Configuration System&quot;">​</a></h2><h3 id="global-configuration" tabindex="-1">Global Configuration <a class="header-anchor" href="#global-configuration" aria-label="Permalink to &quot;Global Configuration&quot;">​</a></h3><p>Located at <code>~/.config/opencode/</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/opencode/</span></span>
<span class="line"><span>├── agents/           # 22 global agents</span></span>
<span class="line"><span>├── skills/           # 67 global skills</span></span>
<span class="line"><span>├── commands/         # 17 global commands</span></span>
<span class="line"><span>├── knowledge/        # 35 knowledge documents</span></span>
<span class="line"><span>├── examples/         # 36 code examples</span></span>
<span class="line"><span>├── playbooks/        # 16 engineering playbooks</span></span>
<span class="line"><span>├── generators/       # 6 workspace generators</span></span>
<span class="line"><span>├── workspace-memory/ # Accumulated knowledge</span></span>
<span class="line"><span>├── metrics/          # Workspace metrics</span></span>
<span class="line"><span>└── AGENTS.md         # Root configuration</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="project-configuration" tabindex="-1">Project Configuration <a class="header-anchor" href="#project-configuration" aria-label="Permalink to &quot;Project Configuration&quot;">​</a></h3><p>Located at <code>.opencode/</code> in your project root:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>├── .opencode/</span></span>
<span class="line"><span>│   ├── agents/       # Project-specific agents</span></span>
<span class="line"><span>│   ├── skills/       # Project-specific skills (14)</span></span>
<span class="line"><span>│   ├── commands/     # Project-specific commands (5)</span></span>
<span class="line"><span>│   └── AGENTS.md     # Project instructions</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="configuration-priority" tabindex="-1">Configuration Priority <a class="header-anchor" href="#configuration-priority" aria-label="Permalink to &quot;Configuration Priority&quot;">​</a></h3><p>Project-level configuration overrides global configuration:</p><ol><li><code>.opencode/</code> (project) — highest priority</li><li><code>~/.config/opencode/</code> (global) — default</li><li>Built-in defaults — fallback</li></ol><hr><h2 id="multi-agent-collaboration" tabindex="-1">Multi-Agent Collaboration <a class="header-anchor" href="#multi-agent-collaboration" aria-label="Permalink to &quot;Multi-Agent Collaboration&quot;">​</a></h2><h3 id="how-agents-work-together" tabindex="-1">How Agents Work Together <a class="header-anchor" href="#how-agents-work-together" aria-label="Permalink to &quot;How Agents Work Together&quot;">​</a></h3><div class="mermaid">sequenceDiagram participant U as User participant B as @build participant F as @frontend participant S as @security participant R as @reviewer U-&gt;&gt;B: Build a user dashboard B-&gt;&gt;B: Analyze requirements B-&gt;&gt;F: Create frontend components F-&gt;&gt;F: Build with React + Tailwind F-&gt;&gt;B: Return components B-&gt;&gt;S: Review for security issues S-&gt;&gt;S: Check auth, validation S-&gt;&gt;B: Return security report B-&gt;&gt;R: Review code quality R-&gt;&gt;R: Check patterns, standards R-&gt;&gt;B: Return review feedback B-&gt;&gt;U: Present complete solution </div><h3 id="conflict-resolution" tabindex="-1">Conflict Resolution <a class="header-anchor" href="#conflict-resolution" aria-label="Permalink to &quot;Conflict Resolution&quot;">​</a></h3><p>When multiple agents have opinions:</p><ol><li><strong>Security overrides all</strong> — security findings always win</li><li><strong>Build-breaking first</strong> — fix before features</li><li><strong>User intent priority</strong> — explicit request &gt; auto-detection</li><li><strong>Agent presentation</strong> — primary agent presents options to user</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/Ahmed-Enterprise-AI-Workspace/workspace-overview">Workspace Overview</a> — What&#39;s inside each component</li><li><a href="/Ahmed-Enterprise-AI-Workspace/folder-structure">Folder Structure</a> — Complete file layout</li><li><a href="/Ahmed-Enterprise-AI-Workspace/glossary">Glossary</a> — All terms defined</li></ul>`,68)])])}const h=e(s,[["render",o]]);export{u as __pageData,h as default};
